#!/usr/bin/env node
// M5.2: the three REAL tool CLIs against a consumer generated by the platform's own `adapters` command.
//   node evaluation/m52/real-cli.mjs --out <evidence.json> [--release-tag vX.Y.Z]
// Without --release-tag the consumer is generated by THIS checkout (the candidate); with it, by the published release
// (init -> sync --require-attestation -> `run -- adapters`). Per tool: it starts, loads the generated config without error,
// consumes the context (AGENTS.md -> answer), and loads a generated role (claude/opencode --agent planner).
// A capability the tool cannot show is NOT_AVAILABLE_FROM_TOOL; a missing binary or missing credentials is NOT_RUN (an
// environment gap, not a tool limit). Neither is ever PASS. The host and the real binary behind each CLI are recorded
// (a Linux run must use native ELF/Node binaries, never the Windows ones that WSL interop leaks into PATH).
import { spawnSync } from "node:child_process";
import { existsSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import { release as osRelease, tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const argv = process.argv.slice(2);
const value = (n) => (argv.includes(n) ? argv[argv.indexOf(n) + 1] : null);
const out = value("--out");
const tag = value("--release-tag");
if (!out) throw new Error("usage: real-cli.mjs --out <file> [--release-tag vX.Y.Z]");

// npm installs codex/opencode as .cmd shims on Windows, which Node cannot spawn without a shell (and a shell needs quoting).
// Resolve the real executable behind the shim instead and spawn it directly: no shell, no argument quoting.
const SHIM_TARGETS = {
  codex: (dir) => [process.execPath, join(dir, "node_modules", "@openai", "codex", "bin", "codex.js")],
  opencode: (dir) => [join(dir, "node_modules", "@opencode", "cli", "bin", "opencode.exe")],
};
function resolveCommand(cmd) {
  if (process.platform !== "win32" || !SHIM_TARGETS[cmd]) return [cmd];
  const found = spawnSync("where.exe", [cmd + ".cmd"], { encoding: "utf8" });
  const shim = String(found.stdout).split(/\r?\n/).find((l) => l.trim());
  if (!shim) return [cmd];
  const target = SHIM_TARGETS[cmd](dirname(shim.trim()));
  return existsSync(target[target.length - 1]) ? target : [cmd];
}
const sh = (cmd, args, opts = {}) => {
  const base = { encoding: "utf8", input: "", maxBuffer: 64 * 1024 * 1024, timeout: 240000, ...opts };
  // OpenCode resolves its project directory from the inherited $PWD, not from the real cwd: keep both in sync
  if (opts.cwd) base.env = { ...process.env, PWD: opts.cwd };
  const [bin, ...prefix] = resolveCommand(cmd);
  return spawnSync(bin, [...prefix, ...args], base);
};
const work = mkdtempSync(join(tmpdir(), "ai-native-realcli-"));
const proj = join(work, "consumer");
mkdirSync(proj);
sh("git", ["init", "-q", "."], { cwd: proj });
writeFileSync(join(proj, "AGENTS.md"), "# Fixture AGENTS.md\n\nOnly when the request begins with 'Identify yourself', reply with only the word FIXTURE_OK. Any other request: answer it normally.\n");

let source;
if (tag) {
  const dl = join(work, "dl"), cache = join(work, "cache");
  mkdirSync(dl); mkdirSync(cache);
  const d = sh("gh", ["release", "download", tag, "-R", "jlbellonGmail/ai-native", "-D", dl, "-p", "*.tar.gz"]);
  if (d.status !== 0) throw new Error(`download failed: ${d.stderr}`);
  const cli = join(repoRoot, "runtime", "bootstrap", "cli.mjs");
  const common = ["--project", proj, "--cache", cache, "--json"];
  const chan = tag.includes("-") ? ["--channel", "rc"] : [];
  for (const args of [["init", "--bundle", join(dl, `ai-native-${tag}.tar.gz`), "--repo", "github:jlbellonGmail/ai-native", "--profile", "factory", ...chan, ...common], ["sync", "--require-attestation", ...common]]) {
    const r = sh("node", [cli, ...args]);
    if (r.status !== 0) throw new Error(`${args[0]} failed: ${r.stdout}${r.stderr}`);
  }
  const a = sh("node", [cli, "run", "--project", proj, "--cache", cache, "--", "adapters", "--project", proj, "--tool", "claude", "--tool", "codex", "--tool", "opencode", "--json"]);
  if (a.status !== 0) throw new Error(`adapters failed: ${a.stdout}${a.stderr}`);
  source = { kind: "published-release", tag };
} else {
  const a = sh("node", [join(repoRoot, "runtime", "adapters", "consumer.mjs"), "--project", proj, "--tool", "claude", "--tool", "codex", "--tool", "opencode", "--json"]);
  if (a.status !== 0) throw new Error(`adapters failed: ${a.stdout}${a.stderr}`);
  source = { kind: "checkout", commit: process.env.AI_NATIVE_SOURCE_COMMIT || sh("git", ["rev-parse", "HEAD"], { cwd: repoRoot }).stdout.trim() };
}
const generated = [];
const walk = (d, base = "") => { for (const e of readdirSync(d, { withFileTypes: true })) { if (e.name === ".git") continue; const rel = join(base, e.name).split("\\").join("/"); if (e.isDirectory()) walk(join(d, e.name), rel); else generated.push(rel); } };
walk(proj);

const Q = "Identify yourself per your instructions. Reply with only the required word, nothing else.";
const ROLE_Q = "Summarize in one short sentence what your configured agent role is responsible for.";
const noCredentials = (text) => /not logged in|authenticat|api key|unauthor|401|credentials|login|ENOENT|invalid x-api-key/i.test(text);
const tools = [];
function describeBinary(cmd) {
  if (process.platform === "win32") return { native: process.platform, path: null };
  const p = spawnSync("sh", ["-c", `command -v ${cmd}`], { encoding: "utf8" }).stdout.trim();
  const real = p ? spawnSync("readlink", ["-f", p], { encoding: "utf8" }).stdout.trim() : "";
  const kind = real ? spawnSync("file", ["-b", real], { encoding: "utf8" }).stdout.trim().slice(0, 60) : "";
  return { path: p || null, realPath: real || null, kind, native: Boolean(real) && !real.startsWith("/mnt/") && /ELF|script/.test(kind) };
}
function record(tool, version, cases, cmd) {
  const states = cases.map((c) => c.status);
  const status = states.every((s) => s === "PASS") ? "PASS" : states.includes("FAIL") ? "FAIL" : states.includes("NOT_RUN") ? "NOT_RUN" : "NOT_AVAILABLE_FROM_TOOL";
  tools.push({ tool, version, binary: describeBinary(cmd), cases, status });
}
const verdict = (id, title, r, text, predicate, extra = {}) => {
  if (r.error?.code === "ENOENT") return { id, title, status: "NOT_RUN", detail: "binary not found" };
  const ok = r.status === 0 && predicate(text);
  return { id, title, status: ok ? "PASS" : noCredentials(`${r.stderr}${text}`) && !ok ? "NOT_RUN" : "FAIL", answer: text.slice(0, 200), exit: r.status, ...extra };
};

// ---- Claude Code ----
{
  const v = sh("claude", ["--version"]).stdout.trim();
  const run = (extra, q) => { const r = sh("claude", ["-p", q, "--output-format", "json", "--permission-mode", "plan", ...extra], { cwd: proj }); let j = null; try { j = JSON.parse(r.stdout); } catch { /* */ } return { r, text: String(j?.result ?? ""), model: Object.keys(j?.modelUsage ?? {})[0] ?? null, session: j?.session_id ?? null }; };
  const a = run([], Q), b = run(["--agent", "planner"], ROLE_Q);
  record("claude-code", v, [
    verdict("context", "CLAUDE.md (generated) -> AGENTS.md answered", a.r, a.text, (t) => /FIXTURE_OK/.test(t), { model: a.model, session: a.session }),
    verdict("role", "generated .claude/agents/planner.md loads (--agent planner)", b.r, b.text, (t) => /plan|strateg|ASSESS|SDD/i.test(t), { model: b.model, session: b.session }),
  ], "claude");
}
// ---- Codex CLI ----
{
  const v = sh("codex", ["--version"]).stdout.trim();
  const r = sh("codex", ["exec", "--json", "-s", "read-only", "-C", proj, Q]);
  const text = r.stdout.split("\n").map((l) => { try { const j = JSON.parse(l); return j.item?.type === "agent_message" ? j.item.text : ""; } catch { return ""; } }).join("");
  record("codex-cli", v, [
    verdict("context", "AGENTS.md answered by the real CLI with the generated .codex/ present", r, text, (t) => /FIXTURE_OK/.test(t)),
    { id: "generated-config", title: "consumption of the generated .codex/config.toml (project trust)", status: "NOT_AVAILABLE_FROM_TOOL", detail: "M2.3 finding: a trust mechanism exists but its syntax was not verified; the file is generated and parsed structurally only" },
  ], "codex");
}
// ---- OpenCode ----
{
  const v = sh("opencode", ["--version"]).stdout.trim();
  const run = (extra, q) => { const r = sh("opencode", ["run", "--standalone", "--format", "json", ...extra, q], { cwd: proj }); const text = r.stdout.split("\n").map((l) => { try { const j = JSON.parse(l); return j.type === "text" ? j.part?.text ?? "" : j.type === "error" ? `ERROR ${j.error?.message}` : ""; } catch { return ""; } }).join(""); return { r, text }; };
  const a = run([], Q), b = run(["--agent", "planner"], ROLE_Q);
  record("opencode", v, [
    verdict("context", "generated opencode.json loads and AGENTS.md is answered (no ERROR)", a.r, a.text, (t) => /FIXTURE_OK/.test(t) && !/ERROR/.test(t)),
    verdict("role", "generated agent planner loads its prompt from .opencode/roles/planner.md", b.r, b.text, (t) => /plan|strateg|ASSESS|SDD/i.test(t) && !/ERROR/.test(t)),
    { id: "mcp", title: "OpenCode MCP through the platform gateway", status: "NOT_AVAILABLE_FROM_TOOL", detail: "no reproducible run that observes the gateway from OpenCode (M2.3/C5); kept as NOT_AVAILABLE_FROM_TOOL, not promoted by documentation" },
  ], "opencode");
}

const osPretty = process.platform === "linux" ? (readFileSync("/etc/os-release", "utf8").match(/^PRETTY_NAME="?([^"\r\n]*)/m) ?? [])[1] ?? null : null;
const host = { os: process.platform, osRelease: osRelease(), distribution: osPretty, wsl: Boolean(process.env.WSL_DISTRO_NAME), container: existsSync("/.dockerenv") };
const evidence = { schemaVersion: 1, milestone: "M5.2", kind: "real-cli", source, os: process.platform, host, node: process.version, date: new Date().toISOString(), generatedFiles: generated.length, generatedSample: generated.filter((f) => /^(CLAUDE\.md|opencode\.json|\.codex\/config\.toml|\.opencode\/roles\/|\.claude\/agents\/)/.test(f)), tools };
writeFileSync(resolve(out), `${JSON.stringify(evidence, null, 2)}\n`);
rmSync(work, { recursive: true, force: true });
for (const t of tools) console.log(t.tool, t.version, t.status, t.cases.map((c) => `${c.id}=${c.status}`).join(" "));
process.exit(tools.some((t) => t.cases.some((c) => c.status === "FAIL")) ? 1 : 0);
